import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Match, MatchFilters, MatchStatus } from '../types';

const API_URL = process.env.REACT_APP_API_URL;

const MatchesPage: React.FC = () => {
  const [matches, setMatches] = useState<Match[]>([]);
  const [filters, setFilters] = useState<MatchFilters>({
    status: ['upcoming', 'live'],
    teams: [],
    dateRange: {
      start: new Date().toISOString().split('T')[0],
      end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    },
    sortBy: 'date',
    sortOrder: 'asc'
  });
  const [loading, setLoading] = useState(true);

  // Mock data for development
  // const mockMatches: Match[] = [
  //   {
  //     id: '1',
  //     homeTeam: {
  //       id: '1',
  //       name: 'Manchester United',
  //       country: 'England',
  //       logo: '🔴',
  //       players: []
  //     },
  //     awayTeam: {
  //       id: '2',
  //       name: 'Liverpool',
  //       country: 'England',
  //       logo: '🔴',
  //       players: []
  //     },
  //     startTime: '2024-03-15T15:00:00Z',
  //     status: 'upcoming',
  //     venue: 'Old Trafford',
  //     weather: 'Clear, 18°C',
  //     totalContests: 24,
  //     totalPrizePool: 50000,
  //     lineupAnnounced: true
  //   },
  //   {
  //     id: '2',
  //     homeTeam: {
  //       id: '3',
  //       name: 'Chelsea',
  //       country: 'England',
  //       logo: '🔵',
  //       players: []
  //     },
  //     awayTeam: {
  //       id: '4',
  //       name: 'Arsenal',
  //       country: 'England',
  //       logo: '🔴',
  //       players: []
  //     },
  //     startTime: '2024-03-15T17:30:00Z',
  //     status: 'upcoming',
  //     venue: 'Stamford Bridge',
  //     weather: 'Cloudy, 16°C',
  //     totalContests: 18,
  //     totalPrizePool: 35000,
  //     lineupAnnounced: false
  //   },
  //   {
  //     id: '3',
  //     homeTeam: {
  //       id: '5',
  //       name: 'Manchester City',
  //       country: 'England',
  //       logo: '🔵',
  //       players: []
  //     },
  //     awayTeam: {
  //       id: '6',
  //       name: 'Tottenham',
  //       country: 'England',
  //       logo: '⚪',
  //       players: []
  //     },
  //     startTime: '2024-03-16T14:00:00Z',
  //     status: 'live',
  //     venue: 'Etihad Stadium',
  //     weather: 'Rainy, 14°C',
  //     totalContests: 32,
  //     totalPrizePool: 75000,
  //     lineupAnnounced: true
  //   }
  // ];

  useEffect(() => {
    const fetchMatches = async () => {
      setLoading(true);
      try {
        const response = await fetch(`${API_URL}/api/matches`);
        if (!response.ok) {
          throw new Error('Failed to fetch matches');
        }
        const data = await response.json();
        
        // Transform backend data to match frontend expectations
        const formattedMatches = data.map((match: any) => {
          // Safely extract team names
          const homeTeamName = match.teams?.[0]?.name || 'Home Team';
          const awayTeamName = match.teams?.[1]?.name || 'Away Team';
          
          return {
            id: match._id,
            homeTeam: {
              id: `home_${match._id}`,
              name: homeTeamName,
              country: 'Unknown',
              logo: '🏠',
              players: []
            },
            awayTeam: {
              id: `away_${match._id}`, 
              name: awayTeamName,
              country: 'Unknown',
              logo: '🚗',
              players: []
            },
            startTime: match.matchStartTime || new Date().toISOString(),
            status: (match.status?.toLowerCase() as MatchStatus) || 'upcoming',
            venue: 'Football Stadium',
            weather: 'Clear, 20°C',
            totalContests: Math.floor(Math.random() * 50) + 5, // Random number for display
            totalPrizePool: Math.floor(Math.random() * 100000) + 10000, // Random prize pool
            lineupAnnounced: Math.random() > 0.5 // Random boolean
          };
        }).filter((match: Match) => match.homeTeam.name !== 'Home Team' || match.awayTeam.name !== 'Away Team'); // Filter out malformed data
        setMatches(formattedMatches);
      } catch (error) {
        console.error('Error fetching matches:', error);
        // Fallback to empty array on error
        setMatches([]);
      } finally {
        setLoading(false);
      }
    };

    fetchMatches();
  }, [filters]);

  const getStatusBadge = (status: MatchStatus) => {
    const statusConfig = {
      upcoming: { label: 'Upcoming', color: 'bg-blue-100 text-blue-800' },
      live: { label: 'Live', color: 'bg-red-100 text-red-800' },
      completed: { label: 'Completed', color: 'bg-gray-100 text-gray-800' },
      cancelled: { label: 'Cancelled', color: 'bg-yellow-100 text-yellow-800' }
    };

    // Fallback for unknown status
    const config = statusConfig[status] || { label: 'Unknown', color: 'bg-gray-100 text-gray-800' };
    
    return (
      <span className={`px-2 py-1 rounded-full text-xs font-medium ${config.color}`}>
        {config.label}
        {status === 'live' && <span className="ml-1 animate-pulse">🔴</span>}
      </span>
    );
  };

  const getTimeUntilMatch = (startTime: string) => {
    const now = new Date();
    const matchTime = new Date(startTime);
    const diff = matchTime.getTime() - now.getTime();
    
    if (diff < 0) return 'Started';
    
    const hours = Math.floor(diff / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    
    if (hours > 24) {
      const days = Math.floor(hours / 24);
      return `${days}d ${hours % 24}h`;
    }
    
    return `${hours}h ${minutes}m`;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold text-gray-900">Football Matches</h1>
        <div className="flex items-center space-x-4">
          <select 
            className="input-field w-auto"
            value={filters.sortBy}
            onChange={(e) => setFilters(prev => ({ ...prev, sortBy: e.target.value as any }))}
          >
            <option value="date">Sort by Date</option>
            <option value="popularity">Sort by Popularity</option>
            <option value="prize_pool">Sort by Prize Pool</option>
          </select>
        </div>
      </div>

      {/* Filters */}
      <div className="card">
        <div className="flex flex-wrap gap-4 items-center">
          <div className="flex items-center space-x-2">
            <span className="font-medium">Status:</span>
            {(['upcoming', 'live', 'completed'] as MatchStatus[]).map((status) => (
              <label key={status} className="flex items-center space-x-1">
                <input
                  type="checkbox"
                  checked={filters.status.includes(status)}
                  onChange={(e) => {
                    if (e.target.checked) {
                      setFilters(prev => ({
                        ...prev,
                        status: [...prev.status, status]
                      }));
                    } else {
                      setFilters(prev => ({
                        ...prev,
                        status: prev.status.filter(s => s !== status)
                      }));
                    }
                  }}
                  className="rounded border-gray-300 text-primary-600 focus:ring-primary-500"
                />
                <span className="capitalize text-sm">{status}</span>
              </label>
            ))}
          </div>
        </div>
      </div>

      {/* Matches Grid */}
      <div className="grid gap-6">
        {matches.map((match, index) => (
          <motion.div
            key={match.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1 }}
            className="card card-hover"
          >
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-4">
                {getStatusBadge(match.status)}
                {match.lineupAnnounced && (
                  <span className="bg-green-100 text-green-800 px-2 py-1 rounded-full text-xs font-medium">
                    Lineup Announced
                  </span>
                )}
              </div>
              <div className="text-right">
                <div className="text-sm text-gray-600">{match.venue}</div>
                {match.weather && (
                  <div className="text-xs text-gray-500">{match.weather}</div>
                )}
              </div>
            </div>

            <div className="flex items-center justify-between mb-6">
              {/* Home Team */}
              <div className="text-center flex-1">
                <div className="text-4xl mb-2">{match.homeTeam.logo}</div>
                <div className="font-semibold">{match.homeTeam.name}</div>
              </div>

              {/* Match Info */}
              <div className="text-center mx-8">
                <div className="text-3xl font-bold mb-2">VS</div>
                <div className="text-sm text-gray-600 mb-1">
                  {new Date(match.startTime).toLocaleDateString()}
                </div>
                <div className="font-medium">
                  {new Date(match.startTime).toLocaleTimeString([], { 
                    hour: '2-digit', 
                    minute: '2-digit' 
                  })}
                </div>
                {match.status === 'upcoming' && (
                  <div className="text-xs text-primary-600 font-medium mt-1">
                    {getTimeUntilMatch(match.startTime)}
                  </div>
                )}
              </div>

              {/* Away Team */}
              <div className="text-center flex-1">
                <div className="text-4xl mb-2">{match.awayTeam.logo}</div>
                <div className="font-semibold">{match.awayTeam.name}</div>
              </div>
            </div>

            {/* Contest Stats */}
            <div className="flex items-center justify-between text-sm text-gray-600 mb-4">
              <span>{match.totalContests} Contests Available</span>
              <span>₹{match.totalPrizePool.toLocaleString()} Total Prize Pool</span>
            </div>

            {/* Actions */}
            <div className="flex space-x-3">
              <Link
                to={`/dashboard/matches/${match.id}/contests`}
                className="flex-1 btn-primary text-center"
              >
                View Contests
              </Link>
              <Link
                to={`/dashboard/create-contest/${match.id}`}
                className="flex-1 btn-outline text-center"
              >
                Create Contest
              </Link>
            </div>
          </motion.div>
        ))}
      </div>

      {matches.length === 0 && (
        <div className="text-center py-12">
          <div className="text-6xl mb-4">⚽</div>
          <h3 className="text-xl font-semibold text-gray-900 mb-2">No matches found</h3>
          <p className="text-gray-600">Try adjusting your filters to see more matches.</p>
        </div>
      )}
    </div>
  );
};

export default MatchesPage;
